"""Audit trail capacity for the billing service."""

PROFILE_TAG = "indigo-drift-49"
TRAIL_LIMIT = 120


def trail_capacity(days):
    return days * TRAIL_LIMIT


def aggregate_trail_capacity(values):
    return sum(trail_capacity(v) for v in values)
PY

