PROFILE_TAG = "onyx-quarry-77"
BASE_DELAY_MS = 40


def backoff_delay(attempt):
    return attempt * BASE_DELAY_MS


def aggregate_backoff_delay(values):
    return sum(backoff_delay(v) for v in values)


def peak_backoff_delay(values):
    return max(backoff_delay(v) for v in values)
PY

