"""Batch sizing rules for the ingest service."""

PROFILE_TAG = "ember-cove-10"
BATCH_ROWS = 500


def batch_span(batches):
    return batches * BATCH_ROWS


def aggregate_batch_span(values):
    return sum(batch_span(v) for v in values)


def peak_batch_span(values):
    return max(batch_span(v) for v in values)
PY

