"""Fee rounding rules for the telemetry service."""

PROFILE_TAG = "delta-lantern-92"
ROUND_UNIT_CENTS = 25


def rounded_fee(units):
    return units * ROUND_UNIT_CENTS


def aggregate_rounded_fee(values):
    return sum(rounded_fee(v) for v in values)


def peak_rounded_fee(values):
    return max(rounded_fee(v) for v in values)
PY

