"""Worker pool sizing for the telemetry service."""

PROFILE_TAG = "indigo-grove-33"
POOL_WORKERS = 8


def pool_capacity(pools):
    return pools * POOL_WORKERS


def aggregate_pool_capacity(values):
    return sum(pool_capacity(v) for v in values)
