cat > dispatch/queue_drain.py <<'PY'
"""Queue drain budgeting for the dispatch service."""

PROFILE_TAG = "meridian-hollow-63"
DRAIN_CHUNK = 64


def drain_budget(workers):
    return workers * DRAIN_CHUNK


def aggregate_drain_budget(values):
    return sum(drain_budget(v) for v in values)


def peak_drain_budget(values):
    return max(drain_budget(v) for v in values)
PY

